const KEY='bailu-web-source-20261101', CHOICE='bailu-promo-counting-disabled';
const TTL=30*60*1000, endpoint='https://api.bailuhub.cn/api/public/site-metrics/v1/event';
const domains=new Set(['www.bailuhub.cn','www.bailuhub.com','bailuhub.cn','bailuhub.com']);
const locales={'en':'en','zh-cn':'zh-cn','zh-tw':'zh-tw'};
function publicPage(path){
 const m=path.match(/^\/(en|zh-cn|zh-tw)(?:\/(learn)(?:\/(first-lesson|getting-started|launch-faq))?|\/(waitlist))?\/?$/);
 if(!m)return null;
 return m[1]+'_'+(m[4]?'waitlist':m[2]?({'first-lesson':'first','getting-started':'guide','launch-faq':'faq'}[m[3]]||'learn'):'home');
}
const keyFor=r=>[r.source,r.campaign,r.content||''].join('|');
const byKey=new Map(REGISTRY.map(r=>[keyFor(r),r]));
function incoming(){
 const q=new URLSearchParams(location.search),take=k=>{const v=q.get(k)||'';return /^[a-zA-Z0-9_-]{1,64}$/.test(v)?v:'';};
 const source=take('utm_source'),campaign=take('utm_campaign'),content=take('utm_content');
 return source&&campaign?byKey.get([source,campaign,content].join('|')):null;
}
function refSource(){
 try{const h=new URL(document.referrer).hostname.toLowerCase();if(/(^|\.)google\.(?:com|cn|co\.uk|com\.hk)$/.test(h))return REGISTRY.find(r=>r.id==='organic_google');if(h==='baidu.com'||h.endsWith('.baidu.com'))return REGISTRY.find(r=>r.id==='organic_baidu');}catch{}
 return REGISTRY.find(r=>r.id==='unattributed');
}
function disabled(){try{return localStorage.getItem(CHOICE)==='1';}catch{return true;}}
let state=null,lastPage='',storageAvailable=true;
function readState(){try{const s=JSON.parse(sessionStorage.getItem(KEY)||'null');return s&&s.expires>Date.now()&&REGISTRY.some(r=>r.id===s.id)?s:null;}catch{storageAvailable=false;return null;}}
function save(){try{sessionStorage.setItem(KEY,JSON.stringify(state));}catch{storageAvailable=false;}}
function resolve(){
 const q=incoming(),old=state||readState();
 if(!old||old.expires<=Date.now()||(q&&q.id!==old.id))state={id:(q||refSource()).id,expires:Date.now()+TTL,entry:false};else state=old;
 save();return REGISTRY.find(r=>r.id===state.id);
}
function fields(r){return {'utm_source':r.source,'utm_campaign':r.campaign,'utm_content':r.content||'',utm_medium:r.kind==='qr'?'qr':r.kind==='organic'?'organic':'social'};}
function decorate(a){
 try{
  const u=new URL(a.getAttribute('href'),location.href);if(!domains.has(u.hostname)||u.protocol!=='https:'||!publicPage(u.pathname))return;
  // Never decorate confirmation, withdrawal, legal, support or arbitrary URLs.
  const r=resolve();if(r.kind==='unknown')return;
  const existing=u.searchParams.get('utm_source');if(existing&&existing!==r.source)return;
  for(const[k,v]of Object.entries(fields(r)))if(v)u.searchParams.set(k,v);
  a.href=u.href;
 }catch{}
}
function propagate(){for(const a of document.querySelectorAll('a[href]'))decorate(a);}
function send(event,page,r){
 if(disabled()||!storageAvailable||document.visibilityState==='hidden')return;
 const q=new URLSearchParams({id:r.id,e:event,p:page});
 // Nothing from forms, email links, fragments, raw referrers or arbitrary query values is sent.
 fetch(endpoint+'?'+q,{method:'GET',mode:'cors',credentials:'omit',cache:'no-store',referrerPolicy:'no-referrer',keepalive:true}).catch(()=>{});
}
function notice(){
 if(document.getElementById('bailu-promo-counting'))return;
 const lang=location.pathname.split('/')[1]||'en',en=lang==='en',tw=lang==='zh-tw';
 const box=document.createElement('aside');box.id='bailu-promo-counting';box.dataset.analyticsExclude='';
 box.style.cssText='padding:16px 24px;background:#f7f6f0;color:#526c73;font:13px/1.8 system-ui;border-top:1px solid #d8e0da';
 const a=document.createElement('a');a.href=`/${lang}/measurement/`;a.textContent=en?'About website campaign counts':tw?'網站推廣計數說明':'网站推广计数说明';a.style.color='#22614c';
 const b=document.createElement('button');b.type='button';b.style.cssText='margin-left:16px;border:1px solid #bccbc3;border-radius:5px;padding:5px 10px;background:transparent;color:#22614c;cursor:pointer';
 const refresh=()=>{b.textContent=disabled()?(en?'Campaign counts: off — enable':tw?'推廣計數已關閉 · 開啟':'推广计数已关闭 · 开启'):(en?'Turn off campaign counts':tw?'關閉推廣計數':'关闭推广计数');};refresh();
 b.addEventListener('click',()=>{try{localStorage.setItem(CHOICE,disabled()?'0':'1');}catch{}refresh();});
 box.append(a,b);document.body.appendChild(box);
}
function start(){
 if(!domains.has(location.hostname)||!publicPage(location.pathname))return;
 // Sensitive fragments fail closed, even on an otherwise public route.
 if(location.hash&&!/^(?:#|#s[0-4]|#ask|#product)$/.test(location.hash))return;
 const page=publicPage(location.pathname),r=resolve();
 if(page.endsWith('_waitlist')&&r.kind!=='unknown'){
  const u=new URL(location.href);for(const[k,v]of Object.entries(fields(r)))if(v)u.searchParams.set(k,v);history.replaceState({},'',u.pathname+u.search);
 }
 propagate();notice();if(document.visibilityState==='hidden')return;if(page===lastPage)return;lastPage=page;
 if(!state.entry&&!disabled()){send('entry',page,r);state.entry=true;save();}
 send(page.endsWith('_waitlist')?'waitlist_view':'view',page,r);
}
document.addEventListener('click',event=>{const a=event.target instanceof Element?event.target.closest('a[href]'):null;if(a)decorate(a);},true);
window.addEventListener('pageshow',start);window.addEventListener('popstate',start);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')start();});
new MutationObserver(()=>{if(publicPage(location.pathname)!==lastPage)start();else propagate();}).observe(document.documentElement,{attributes:true,attributeFilter:['lang']});
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start,{once:true});else start();
